import type { JsonSchema } from "./types.ts";

export type OperationSideEffect = "read" | "write";
export type RequiredScope = "none" | "tenant" | "bookSet" | "taxCase";
export type TransportPolicy = "ALL" | "CLI_ONLY";

export interface OperationCatalogEntry {
  readonly id: string;
  readonly description: string;
  readonly sideEffect: OperationSideEffect;
  readonly requiredScope: RequiredScope;
  readonly inputSchema: JsonSchema;
  readonly outputDescription: string;
  readonly examples: readonly string[];
  readonly remediation: string;
  readonly operatorOnly?: boolean;
  readonly transportPolicy?: TransportPolicy;
}

const objectSchema = (required: readonly string[] = [], properties: Record<string, unknown> = {}): JsonSchema => ({
  type: "object",
  properties,
  required: [...required],
  additionalProperties: true,
});

const id = { type: "string", minLength: 1 };
const date = { type: "string", pattern: "^\\d{4}-\\d{2}-\\d{2}$" };
const envelopeProperties = {
  schemaVersion: { type: "number", const: 1 }, tenantId: id, requestId: id,
  actor: { type: "object", required: ["kind", "id"] }, source: { type: "string" },
  reason: { type: "string", minLength: 1 }, requestedAt: { type: "string" }, payload: { type: "object" },
};
const scopedEnvelopeProperties = { ...envelopeProperties, bookSetId: id };
const readScopeProperties = { tenantId: id, bookSetId: id };
const companyStatusProperties = { tenantId: id, bookSetId: id, taxCaseId: id, asOfDate: date, asOfTimestamp: { type: "string", minLength: 1 }, focus: { type: "string", minLength: 1 } };
const commandSchema = (bookSet: boolean, payloadRequired = true) => objectSchema(
  bookSet ? ["schemaVersion", "tenantId", "bookSetId", "requestId", "actor", "source", "reason", ...(payloadRequired ? ["payload"] : [])] : ["schemaVersion", "tenantId", "requestId", "actor", "source", "reason", ...(payloadRequired ? ["payload"] : [])],
  bookSet ? scopedEnvelopeProperties : envelopeProperties,
);
const sourceFileSchema = objectSchema(
  ["schemaVersion", "tenantId", "bookSetId", "requestId", "actor", "source", "reason", "payload"],
  {
    ...scopedEnvelopeProperties,
    payload: {
      type: "object",
      properties: {
        filePath: { type: "string", minLength: 1 },
        bankAccountId: id,
        parserId: { type: "string", enum: ["SCB_TRANSACTION_CSV_V1", "CRAZE_VIRTUAL_ACCOUNT_CSV_V1"] },
        periodStart: date,
        periodEnd: date,
        authorityState: { type: "string", enum: ["PRIMARY", "DERIVED", "UNVERIFIED"] },
        overrideReason: { type: "string", minLength: 1 },
      },
      required: ["filePath", "bankAccountId", "parserId"],
      additionalProperties: true,
    },
  },
);
const sourceStagingSchema = objectSchema(
  ["schemaVersion", "tenantId", "bookSetId", "requestId", "actor", "source", "reason", "payload"],
  { ...scopedEnvelopeProperties, payload: { type: "object", properties: { sourcePath: { type: "string", minLength: 1 }, parserId: { type: "string", enum: ["SCB_DERIVED_TRANSACTION_CSV_V1", "MUNIM_SALES_REGISTER_PDF_V1", "MUNIM_TRIAL_BALANCE_PDF_V1", "MUNIM_EXPENSE_SUMMARY_PDF_V1", "MUNIM_TDS_REPORT_PDF_V1", "MUNIM_PAYMENT_RECEIVED_PDF_V1", "MUNIM_SALES_INVOICE_VIEW_PDF_V1"] }, periodStart: date, periodEnd: date, authorityState: { type: "string", enum: ["PRIMARY", "DERIVED", "UNVERIFIED"] } }, required: ["sourcePath", "parserId"], additionalProperties: true } },
);

