export const OPERATION_CATALOG: readonly OperationCatalogEntry[] = entries;
export const BUSINESS_OPERATION_CATALOG = OPERATION_CATALOG.filter((entry) => !entry.operatorOnly);

export const MCP_OPERATION_CATALOG = OPERATION_CATALOG.filter((entry) => entry.transportPolicy !== "CLI_ONLY");

export function findOperation(id: string, includeOperator = true): OperationCatalogEntry | undefined {
  return OPERATION_CATALOG.find((entry) => entry.id === id && (includeOperator || !entry.operatorOnly));
}
